const fs=require('fs'),p=require('path');const root=p.resolve(__dirname,'..'),out=p.join(root,'firmware-analiza'),read=f=>JSON.parse(fs.readFileSync(p.join(out,f),'utf8')),audit=read('audit.json'),bins=read('fisiere-binare.json'),models=read('modele-audio.json'),refs=read('dovezi-sursa.json'),aot=read('indicii-dart-ota.json');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const link=(file,line,text)=>'<a href="../reconstituit/jadx/app/src/main/java/'+file+'">'+esc(text||file)+'</a> · linia '+line;const ota='com/example/recorde_translate_plugin/glass/GlassOTAManager.java',plug='com/example/recorde_translate_plugin/glass/wifip2p/WifiManagerPlugin.java';
const primary=[{title:'Ghidra: dezasamblare și decompilare',url:'https://github.com/NationalSecurityAgency/ghidra'},{title:'Ghidra: documentația decompilatorului',url:'https://github.com/NationalSecurityAgency/ghidra/blob/master/Ghidra/Features/Decompiler/src/main/doc/decompileplugin.xml'},{title:'Android: directoare private ale aplicației',url:'https://developer.android.com/training/data-storage/app-specific'},{title:'Android Debug Bridge',url:'https://developer.android.com/tools/adb'}];
let html='<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Firmware iFLYTEK: posibilități și dovezi</title><link rel="stylesheet" href="../catalog-parametri-functii/catalog.css"></head><body><header><div class="eyebrow">iFLYTEK · audit firmware · 30 octombrie 2026</div><h1>Firmware: ce putem extrage și ce ne lipsește</h1><nav><a href="../INDEX.html">Catalog APK</a><a href="../catalog-parametri-functii/INDEX.html">Parametri și funcții</a><a href="../protocol-comunicare/INDEX.html">Protocol</a><a href="audit.json">Audit JSON</a></nav></header><main class="wrap"><p><strong>Da, o imagine de firmware poate fi analizată prin dezasamblare și decompilare, dacă formatul și arhitectura sunt accesibile.</strong> Pentru ochelarii analizați, nu avem încă un pachet de firmware identificat. Avem codul Android al actualizării și indicii din Dart AOT despre obținerea pachetului.</p><div class="cards"><article><div class="metric">'+audit.binaryAssets+'</div>fișiere binare candidate din APK</article><article><div class="metric">'+audit.archivesScanned+'</div>arhive locale inspectate după numele intrărilor</article><article><div class="metric">'+audit.confirmedGlassesFirmwareImages+'</div>imagini de firmware confirmate pentru acest model</article></div><h2>Ce confirmă codul aplicației</h2><table><tr><th>Dovadă</th><th>Ce permite să afirmăm</th><th>Sursă</th></tr><tr><td><code>startGlassOTA(path, otaVer)</code></td><td>Flutter transmite o cale locală și versiunea către managerul Android.</td><td>'+link(plug,513,'WifiManagerPlugin')+'</td></tr><tr><td><code>startOTA(String filePath, String otaVersion, ...)</code></td><td>Managerul primește un fișier; dacă filePath este gol, folosește getFilesDir() + /ota_package.bin.</td><td>'+link(ota,1450,'GlassOTAManager.startOTA')+'</td></tr><tr><td>Dimensiune, MD5, transfer și stare OTA</td><td>Aplicația pregătește și transferă un pachet. MD5 nu dovedește că pachetul este decriptat, nesemnat sau acceptă modificări.</td><td>'+link(ota,735,'GlassOTAManager.enterOTA')+'</td></tr><tr><td><code>/hardware/upgrade/checkFirmwareVersion</code></td><td>Șir extras din libapp.so. Este indiciu de rută pentru verificarea versiunii, nu un contract HTTP reconstituit.</td><td><a href="indicii-dart-ota.json">Șiruri AOT și offseturi</a></td></tr><tr><td><code>allowBackup="false"</code>; debuggable nu este activat în manifest</td><td>Nu ne putem baza pe backupul obișnuit sau pe run-as pentru acces la datele versiunii de producție. Comportamentul telefonului trebuie verificat separat.</td><td><a href="../reconstituit/jadx/app/src/main/AndroidManifest.xml">AndroidManifest.xml, linia 132</a></td></tr></table><p>Calea implicită uzuală pentru utilizatorul Android 0 este <code>/data/user/0/com.iflytek.translateapp/files/ota_package.bin</code>. Este o deducție din getFilesDir(), nu un fișier găsit pe telefon. O cale explicită trimisă în argumentul path poate fi complet diferită.</p><h2>Ce am verificat în materialele existente</h2><div class="scroll"><table><tr><th>Fișier</th><th>Octeți</th><th>Clasificare</th></tr>'+bins.map(x=>'<tr><td><code>'+esc(x.file)+'</code></td><td>'+x.bytes.toLocaleString('ro-RO')+'</td><td>'+esc(x.classification)+(x.modelJson?' <a href="'+x.modelJson+'">Structură extrasă</a>':'')+'</td></tr>').join('')+'</table></div><p>Modelele <code>ant_iflytekair2...</code> și <code>ant_rayneov4...</code> sunt copiate din assets și încărcate de AgseEncoder. Fișierele FYJ2mic conțin un graf de rețea neuronală și date binare asociate. Numele <code>aes_...</code> din model_info nu este, singur, dovadă de criptare AES.</p><p>În arhiva de documentație Rokid, intrarea payload.bin de 134 octeți este un pointer Git LFS către un obiect de 906.017.679 octeți, nu conținutul firmware-ului. Se referă oricum la un alt produs. Celelalte potriviri sunt cod OTA / exemple, fără identificarea unui firmware iFLYTEK pentru ochelari.</p><p><a href="fisiere-binare.json">Antete, dimensiuni și SHA-256</a> · <a href="arhive-candidati.json">Intrări din arhive</a> · <a href="urluri-candidate-ota.json">URL-uri directe candidate</a> · <a href="modele-audio.json">Modele extrase</a></p><h2>Ce se poate recupera dintr-un firmware accesibil</h2><table><tr><th>Artefact</th><th>Rezultat realist</th></tr><tr><td>Cod mașină pentru CPU / MCU</td><td>Instrucțiuni, funcții identificate, graful apelurilor, referințe la date și pseudocod apropiat de C, în funcție de arhitectură și calitatea analizei.</td></tr><tr><td>Sistem de fișiere / partiții</td><td>Executabile, biblioteci, configurații, resurse și modele, dacă sunt prezente și se pot decoda.</td></tr><tr><td>Comenzi și protocoale</td><td>Handler-e pentru codurile opt, parseri, structuri, validări și limite efective, care pot fi corelate cu dicționarele aplicației.</td></tr><tr><td>Cod nativ optimizat / fără simboluri</td><td>Numele originale, tipurile, comentariile și separarea inițială în fișiere C/C++ nu sunt garantate. Funcțiile inline pot să nu mai existe separat.</td></tr><tr><td>Modele și servicii cloud</td><td>Pot exista resurse sau clienți în firmware. Codul backend și modelul cloud nu se recuperează dintr-un dispozitiv care doar apelează serviciul.</td></tr></table><p>Arhitectura procesorului ochelarilor, limbajul sursă, sistemul de operare și formatul pachetului nu sunt confirmate de acest audit. ARM64-ul din libapp.so descrie aplicația Android, nu demonstrează arhitectura ochelarilor.</p><h2>Condiții care schimbă metoda de analiză</h2><ul><li><b>Pachet comprimat:</b> se identifică formatul și se despachetează.</li><li><b>Actualizare diferențială:</b> poate fi necesară imaginea versiunii de bază pentru reconstrucție.</li><li><b>Pachet criptat:</b> este necesar conținutul lizibil sau mecanismul legitim de decriptare; entropia ridicată nu dovedește singură criptarea.</li><li><b>Pachet semnat:</b> semnătura poate permite verificarea originii și poate bloca instalarea unui pachet modificat; nu implică automat imposibilitatea citirii codului.</li><li><b>Citire directă din dispozitiv:</b> posibilitatea depinde de interfețele hardware expuse și protecția memoriei; nu presupunem că USB, JTAG sau SWD permit extragerea.</li></ul><h2>Traseul concret pentru telefonul Android al utilizatorului</h2><ol><li>Se identifică în aplicație modelul, versiunea firmware și disponibilitatea unei actualizări. Utilizatorul are ochelarii și Android; nu a descărcat încă o actualizare.</li><li>Se urmărește obținerea metadatelor și a pachetului destinat acestui model: versiune, URL, dimensiune, hash și cale locală. Nu se presupune că butonul de actualizare separă descărcarea de instalare.</li><li>Se verifică accesul la fișier prin exportul aplicației, stocare accesibilă sau un mediu de analiză autorizat. ADB singur nu oferă acces universal la directorul privat al unei aplicații de producție.</li><li>Pachetul recuperat se păstrează nemodificat, cu SHA-256. Se identifică antetul, compresia, partițiile, arhitectura și eventualele dependențe de o versiune anterioară.</li><li>Se importă componentele executabile într-un analizor potrivit, se exportă funcțiile / pseudocodul și se leagă rezultatele de catalogul parametrilor și comenzilor.</li></ol><p>Nu am rulat o actualizare, nu am modificat ochelarii și nu am accesat telefonul. Nu este disponibil încă fișierul de intrare pentru decompilarea firmware-ului acestui model.</p><h2>Surse primare și dovezi locale</h2><ul>'+primary.map(x=>'<li><a href="'+x.url+'">'+esc(x.title)+'</a></li>').join('')+'</ul><p>Documentația generică iFLYOS OTA nu a fost tratată drept contract al acestor ochelari.</p><details><summary>Dovezi Java</summary>'+refs.map(x=>'<div class="source">'+link(x.file,x.line)+'<pre>'+esc(x.excerpt)+'</pre></div>').join('')+'</details></main></body></html>';
fs.writeFileSync(p.join(out,'INDEX.html'),html);fs.writeFileSync(p.join(out,'surse-web.json'),JSON.stringify(primary,null,2));
for(const [name,href] of [[p.join(root,'INDEX.html'),'firmware-analiza/INDEX.html'],[p.join(root,'catalog-parametri-functii/INDEX.html'),'../firmware-analiza/INDEX.html'],[p.join(root,'protocol-comunicare/INDEX.html'),'../firmware-analiza/INDEX.html']]){let s=fs.readFileSync(name,'utf8'),snippet='<p id="audit-firmware" style="padding:16px;background:#e7f3f9"><a href="'+href+'"><b>Firmware: decompilare, pachet OTA și inventarul fișierelor disponibile</b></a></p>';if(s.includes('id="audit-firmware"'))s=s.replace(/<p id="audit-firmware"[\s\S]*?<\/p>/,snippet);else s=s.replace(/(<body[^>]*>)/i,'$1'+snippet);fs.writeFileSync(name,s);}
const broken=[];for(const m of html.matchAll(/(?:href|src)="([^"]+)"/g)){if(/^https?:/.test(m[1]))continue;if(!fs.existsSync(p.resolve(out,m[1])))broken.push(m[1]);}if(broken.length)throw Error('Missing links '+broken.join(', '));console.log(JSON.stringify({html:true,brokenLinks:broken,neuralGraphs:models.length,aotClues:aot.length}));
